            ['text' => 'What happens when people open their hearts? They get better.', 'author' => 'Haruki Murakami', 'category' => 'Healing'],
            ['text' => 'Healing requires from us to stop struggling, but to enjoy life more and endure it less.', 'author' => 'Darina Stoyanova', 'category' => 'Healing'],
            ['text' => 'Emotional pain cannot kill you, but running from it can. Allow. Embrace. Let yourself feel. Let yourself heal.', 'author' => 'Vironika Tugaleva', 'category' => 'Healing'],
            ['text' => 'The practice of forgiveness is our most important contribution to the healing of the world.', 'author' => 'Marianne Williamson', 'category' => 'Healing'],
            ['text' => 'I have come to believe that caring for myself is not self-indulgent. Caring for myself is an act of survival.', 'author' => 'Audre Lorde', 'category' => 'Healing'],
